def parser(log: str) -> dict[str, str]:
    import re
    import xml.etree.ElementTree as ET

    results: dict[str, str] = {}
    rank = {"pass": 0, "skip": 1, "fail": 2}

    def record(name: str | None, status: str) -> None:
        if not name:
            return
        name = name.strip()
        if not name:
            return
        current = results.get(name)
        if current is None or rank[status] > rank[current]:
            results[name] = status

    def normalize_status(value: str, default: str = "fail") -> str:
        v = (value or "").strip().lower()
        if v in ("passed", "pass", "success", "ok"):
            return "pass"
        if v in ("skipped", "skip", "notexecuted", "ignored", "disabled", "pending", "inconclusive"):
            return "skip"
        if v in ("failed", "fail", "failure", "error", "timeout", "aborted", "crash"):
            return "fail"
        return default

    def parse_root(root: ET.Element) -> None:
        for elem in root.iter():
            tag = elem.tag.rsplit("}", 1)[-1].lower()
            if tag == "unittestresult":
                name = elem.attrib.get("testName") or elem.attrib.get("name")
                status = normalize_status(elem.attrib.get("outcome", ""))
                record(name, status)
            elif tag == "testcase":
                name = elem.attrib.get("name")
                classname = elem.attrib.get("classname") or elem.attrib.get("class")
                if classname and name and not name.startswith(classname):
                    name = f"{classname}.{name}"
                status_attr = elem.attrib.get("status") or elem.attrib.get("result") or ""
                status = normalize_status(status_attr, default="pass")
                for child in elem:
                    ctag = child.tag.rsplit("}", 1)[-1].lower()
                    if ctag in ("failure", "error"):
                        status = "fail"
                        break
                    if ctag == "skipped":
                        status = "skip"
                record(name, status)
            elif tag == "test-case":
                name = elem.attrib.get("fullname") or elem.attrib.get("name")
                status = normalize_status(elem.attrib.get("result") or elem.attrib.get("outcome") or "", default="pass")
                label = (elem.attrib.get("label") or "").lower()
                if label == "skipped":
                    status = "skip"
                record(name, status)

    def try_parse_xml(text: str) -> None:
        try:
            root = ET.fromstring(text)
        except ET.ParseError:
            return
        parse_root(root)

    def parse_attrs(attr_text: str) -> dict[str, str]:
        attrs: dict[str, str] = {}
        for m in re.finditer(r'([\w:.-]+)\s*=\s*("([^"]*)"|\'([^\']*)\')', attr_text):
            key = m.group(1)
            val = m.group(3) if m.group(3) is not None else m.group(4)
            attrs[key] = val
        return attrs

    log = (log or "").replace("\ufeff", "")

    blocks: list[str] = []
    for tag in ("TestRun", "testsuites", "testsuite", "test-run"):
        for m in re.finditer(rf"<{tag}\b", log):
            start = m.start()
            end = log.find(f"</{tag}>", start)
            if end != -1:
                blocks.append(log[start:end + len(tag) + 3])

    prologs = [m.start() for m in re.finditer(r"<\?xml", log)]
    if prologs:
        prologs.append(len(log))
        for i in range(len(prologs) - 1):
            blocks.append(log[prologs[i]:prologs[i + 1]])

    if blocks:
        for block in blocks:
            try_parse_xml(block)
    else:
        try_parse_xml(log.strip())

    # Regex fallback for TRX UnitTestResult tags
    for m in re.finditer(r"<UnitTestResult\b([^>]*)>", log, re.IGNORECASE | re.DOTALL):
        attrs = parse_attrs(m.group(1))
        attrs_lower = {k.lower(): v for k, v in attrs.items()}
        name = attrs_lower.get("testname") or attrs_lower.get("name")
        status = normalize_status(attrs_lower.get("outcome", ""))
        record(name, status)

    # Regex fallback for JUnit testcase tags
    for m in re.finditer(r"<testcase\b([^>/]*)(?:/?>|>([\s\S]*?)</testcase>)", log, re.IGNORECASE):
        attrs = parse_attrs(m.group(1))
        attrs_lower = {k.lower(): v for k, v in attrs.items()}
        content = m.group(2) or ""
        name = attrs_lower.get("name")
        classname = attrs_lower.get("classname") or attrs_lower.get("class")
        if classname and name and not name.startswith(classname):
            name = f"{classname}.{name}"
        if re.search(r"<(failure|error)\b", content, re.IGNORECASE):
            status = "fail"
        elif re.search(r"<skipped\b", content, re.IGNORECASE):
            status = "skip"
        else:
            status = normalize_status(attrs_lower.get("status", ""), default="pass")
        record(name, status)

    # Text-based patterns
    for line in log.splitlines():
        line = line.strip()
        if not line:
            continue
        m = re.match(r"^(\S+::\S.*?)\s+(PASSED|FAILED|SKIPPED|ERROR|XFAIL|XPASS)\b", line)
        if m:
            name, outcome = m.group(1), m.group(2).lower()
            status = "fail" if outcome == "xpass" else ("skip" if outcome == "xfail" else normalize_status(outcome))
            record(name, status)
            continue

        m = re.match(r"^(\S+\.\S+)\s+\.\.\.\s+(ok|FAIL|ERROR|skipped)\b", line, re.IGNORECASE)
        if m:
            name, outcome = m.group(1), m.group(2)
            record(name, normalize_status(outcome, default="pass"))
            continue

        m = re.match(r"^---\s+(PASS|FAIL|SKIP):\s+(\S+)", line)
        if m:
            record(m.group(2), normalize_status(m.group(1)))
            continue

        m = re.match(r"^[✓√]\s+(.*)$", line)
        if m:
            record(m.group(1).strip(), "pass")
            continue
        m = re.match(r"^[✕×✖]\s+(.*)$", line)
        if m:
            record(m.group(1).strip(), "fail")
            continue
        m = re.match(r"^[○◌]\s+(.*)$", line)
        if m:
            record(m.group(1).strip(), "skip")
            continue

    return results
